package com.bananalab.lite;
/** Finite arithmetic AST. No Java API access, statements, allocation, loops or recursion. */
final class JavaCurve{
 static final class Node{String op;float value;Node a,b,c;Node(String o,float v,Node x,Node y,Node z){op=o;value=v;a=x;b=y;c=z;}
  float at(float t){switch(op){case "n":return value;case "t":return t;case "+":return a.at(t)+b.at(t);case "-":return a.at(t)-b.at(t);case "*":return a.at(t)*b.at(t);case "/":return a.at(t)/b.at(t);case "neg":return -a.at(t);case "sin":return (float)Math.sin(a.at(t));case "cos":return (float)Math.cos(a.at(t));case "abs":return Math.abs(a.at(t));case "min":return Math.min(a.at(t),b.at(t));case "max":return Math.max(a.at(t),b.at(t));default:boolean yes=op.equals("<")?t<value:op.equals("<=")?t<=value:op.equals(">")?t>value:t>=value;return yes?b.at(t):c.at(t);}}
  String java(){if(op.equals("n"))return Float.toString(value)+"f";if(op.equals("t"))return "t";if(op.equals("neg"))return "(-"+a.java()+")";if(op.matches("[+*/-]"))return "("+a.java()+op+b.java()+")";if(op.matches("sin|cos|abs|min|max"))return "((float)Math."+op+"("+a.java()+(b==null?"":","+b.java())+"))";return "(t"+op+value+"f?"+b.java()+":"+c.java()+")";}}
 final String input;int pos,nodes,depth;final Node root;
 JavaCurve(String text){if(text==null||text.length()>1000)throw new IllegalArgumentException("La fórmula admite hasta1000 caracteres.");if(text.matches("(?s).*[0-9.]\\s+[0-9.].*"))throw new IllegalArgumentException("Separá los números con un operador.");input=text.replaceAll("\\s+","");root=expression();if(pos!=input.length())throw new IllegalArgumentException("Símbolo no admitido en la fórmula: "+input.substring(pos,Math.min(pos+15,input.length())));for(int i=0;i<=256;i++){float v=root.at(i/256f);if(Float.isNaN(v)||Float.isInfinite(v))throw new IllegalArgumentException("La fórmula produjo un valor no finito.");}if(Math.abs(value(0))>.01||Math.abs(value(1))>.01)throw new IllegalArgumentException("El salto debe empezar y terminar en el suelo (valor0).");}
 Node node(String op,float v,Node a,Node b,Node c){if(++nodes>120)throw new IllegalArgumentException("La fórmula tiene demasiadas operaciones.");return new Node(op,v,a,b,c);}
 boolean take(String x){if(input.startsWith(x,pos)){pos+=x.length();return true;}return false;}
 Node expression(){if(++depth>20)throw new IllegalArgumentException("La fórmula está demasiado anidada.");Node a=sum();String cmp=null;for(String op:new String[]{"<=",">=","<",">"})if(take(op)){cmp=op;break;}if(cmp!=null){if(!a.op.equals("t"))throw new IllegalArgumentException("Las condiciones comparan t con un número de0 a1.");Node n=primary();if(!n.op.equals("n")||n.value<0||n.value>1||!take("?"))throw new IllegalArgumentException("Usá t < número ? subida : bajada.");Node b=expression();if(!take(":"))throw new IllegalArgumentException("Falta la segunda parte de la condición.");Node c=expression();a=node(cmp,n.value,a,b,c);}depth--;return a;}
 Node sum(){Node a=product();while(pos<input.length()){if(take("+"))a=node("+",0,a,product(),null);else if(take("-"))a=node("-",0,a,product(),null);else break;}return a;}
 Node product(){Node a=primary();while(pos<input.length()){if(take("*"))a=node("*",0,a,primary(),null);else if(take("/")){Node b=primary();if(!b.op.equals("n")||Math.abs(b.value)<.001)throw new IllegalArgumentException("Solo se puede dividir por constantes no nulas.");a=node("/",0,a,b,null);}else break;}return a;}
 Node primary(){if(++depth>20)throw new IllegalArgumentException("La fórmula está demasiado anidada.");Node n;if(take("-"))n=node("neg",0,primary(),null,null);else if(take("(")){n=expression();if(!take(")"))throw new IllegalArgumentException("Falta cerrar un paréntesis.");}else if(take("t"))n=node("t",0,null,null,null);else{int start=pos;while(pos<input.length()&&(Character.isDigit(input.charAt(pos))||input.charAt(pos)=='.'))pos++;if(pos>start){float v;try{v=Float.parseFloat(input.substring(start,pos));}catch(Exception e){throw new IllegalArgumentException("Número no válido.");}take("f");if(Float.isNaN(v)||Float.isInfinite(v)||v>1000)throw new IllegalArgumentException("Las constantes deben estar entre0 y1000.");n=node("n",v,null,null,null);}else{take("Math.");String op=null;for(String word:new String[]{"sin","cos","abs","min","max"})if(take(word+"(")){op=word;break;}if(op==null)throw new IllegalArgumentException("Usá t, números, + - * /, sin, cos, abs, min, max y condiciones de fase.");Node a=expression(),b=null;if(op.equals("min")||op.equals("max")){if(!take(","))throw new IllegalArgumentException("La función necesita dos valores.");b=expression();}if(!take(")"))throw new IllegalArgumentException("Falta cerrar la función.");n=node(op,0,a,b,null);}}depth--;return n;}
 float value(float t){return Math.max(-40,Math.min(0,root.at(Math.max(0,Math.min(1,t)))));}
 String source(){return "package com.bananalab.patch;\npublic final class BananaFunction {\n public static float jump(float t) { return Math.max(-40f, Math.min(0f, "+root.java()+")); }\n}\n";}
 static String natural(int height,int up,int until){if(height<1||height>40||up<5||until<up||until>95)throw new IllegalArgumentException("Altura1–40; subida desde5%; fin de pausa antes del95%.");return "t < "+up/100f+" ? -"+height+" * t / "+up/100f+" : (t < "+until/100f+" ? -"+height+" : -"+height+" * (1-t) / "+(100-until)/100f+")";}
}
